import app from 'flarum/forum/app';
import extractText from 'flarum/common/utils/extractText';
export const t = (key, params = {}) => app.translator.trans(`ernestdefoe-club.forum.${key}`, params);
export const text = (key, params = {}) => extractText(t(key, params));

// Core puts dayjs on window (with its locale and plugins) rather than exporting
// it as a module, so it is read here once and nowhere else.
const day = value => dayjs(value);
export const monthName = month => month ? day(month).format('MMMM YYYY') : '';
export const dueDate = due => due ? day(due).format('ll') : null;
/** Whether a due date (YYYY-MM-DD) is before today. */
export const isOverdue = due => day(due).isBefore(day(), 'day');
/** This month, YYYY-MM. */
export const thisMonth = () => day().format('YYYY-MM');
export const apiUrl = path => `${app.forum.attribute('apiUrl')}/${path}`;

/** "Section 2 · Chapters 6–10" */
export const sectionName = (pick, n) => {
  const section = (pick.sections() || [])[n - 1];
  return section ? text('section.name', {
    number: n,
    label: section.label
  }) : text('section.number', {
    number: n
  });
};