import Model from 'flarum/common/Model';
export class Club extends Model {
  name() {
    return Model.attribute('name').call(this);
  }
  description() {
    return Model.attribute('description').call(this);
  }
  memberCount() {
    return Model.attribute('memberCount').call(this);
  }
  createdAt() {
    return Model.attribute('createdAt', Model.transformDate).call(this);
  }
  /** host | member | null */
  viewerRole() {
    return Model.attribute('viewerRole').call(this);
  }
  canEdit() {
    return Model.attribute('canEdit').call(this);
  }
  canJoin() {
    return Model.attribute('canJoin').call(this);
  }
  user() {
    return Model.hasOne('user').call(this);
  }
  picks() {
    return Model.hasMany('picks').call(this);
  }
}
export class Pick extends Model {
  month() {
    return Model.attribute('month').call(this);
  }
  sections() {
    return Model.attribute('sections').call(this);
  }
  /** Sections the viewer has finished; null when not in the club. */
  viewerDone() {
    return Model.attribute('viewerDone').call(this);
  }
  progress() {
    return Model.attribute('progress').call(this);
  }
  club() {
    return Model.hasOne('club').call(this);
  }
  discussion() {
    return Model.hasOne('discussion').call(this);
  }
  media() {
    return Model.hasOne('media').call(this);
  }
}