import Button from 'flarum/common/components/Button';
import { setProgress } from '../api';
import { t, sectionName } from '../util';

/** In place of a reply about a section the reader hasn't finished. */
export default function spoilerNotice(post) {
  const discussion = post.discussion();
  const pick = discussion && discussion.clubPick();
  const section = post.attribute('clubSection');
  const club = pick && pick.club();
  const member = club && club.viewerRole();
  return m("div", {
    className: "ClubSpoiler"
  }, m("i", {
    className: "fas fa-eye-slash",
    "aria-hidden": "true"
  }), m("div", null, m("b", null, t('spoiler.title', {
    section: pick ? sectionName(pick, section) : section
  })), m("p", null, t(member ? 'spoiler.body_member' : 'spoiler.body')), pick && member ? m(Button, {
    className: "Button",
    onclick: () => setProgress(pick, section).then(() => m.redraw())
  }, t('spoiler.finished', {
    section: sectionName(pick, section)
  })) : null));
}
flarum.reg.add('ernestdefoe-club', 'forum/components/SpoilerNotice', spoilerNotice);